-- Modify "sys_modeldev_acceptances" table
ALTER TABLE "public"."sys_modeldev_acceptances" ADD CONSTRAINT "sys_modeldev_acceptances_close_counters_ck" CHECK ((close_attempt_count >= 0) AND (close_lease_generation >= 0)), ADD CONSTRAINT "sys_modeldev_acceptances_close_due_ck" CHECK (((close_dispatch_state)::text = 'UNKNOWN'::text) OR ((close_next_attempt_at IS NULL) AND (close_retry_blocked = false))), ADD CONSTRAINT "sys_modeldev_acceptances_close_error_ck" CHECK ((close_last_error_code IS NULL) OR ((close_last_error_code)::text = ANY ((ARRAY['INVALID_COMMAND'::character varying, 'COMMAND_CONFLICT'::character varying, 'OWNER_UNAVAILABLE'::character varying, 'INVALID_ACK'::character varying, 'LEASE_EXHAUSTED'::character varying, 'ATTEMPTS_EXHAUSTED'::character varying])::text[]))), ADD CONSTRAINT "sys_modeldev_acceptances_close_lease_ck" CHECK ((((close_dispatch_state)::text = 'DISPATCHING'::text) AND (close_lease_owner IS NOT NULL) AND ((length((close_lease_owner)::text) >= 1) AND (length((close_lease_owner)::text) <= 128)) AND (close_lease_until IS NOT NULL) AND (close_lease_generation > 0)) OR (((close_dispatch_state)::text <> 'DISPATCHING'::text) AND (close_lease_owner IS NULL) AND (close_lease_until IS NULL))), ADD CONSTRAINT "sys_modeldev_acceptances_close_receipt_ck" CHECK ((((close_dispatch_state)::text = 'ACKED'::text) AND (close_receipt_canonical IS NOT NULL) AND ((octet_length(close_receipt_canonical) >= 1) AND (octet_length(close_receipt_canonical) <= 4096))) OR (((close_dispatch_state)::text <> 'ACKED'::text) AND (close_receipt_canonical IS NULL))), ADD CONSTRAINT "sys_modeldev_acceptances_stop_intent_ck" CHECK (((stop_intent_generation = 0) AND (stop_requested_at IS NULL) AND (stop_requested_actor IS NULL) AND ((close_dispatch_state)::text = 'IDLE'::text)) OR ((stop_intent_generation > 0) AND (stop_requested_at IS NOT NULL) AND (stop_requested_actor IS NOT NULL) AND ((length((stop_requested_actor)::text) >= 1) AND (length((stop_requested_actor)::text) <= 128)) AND ((close_dispatch_state)::text = ANY ((ARRAY['QUEUED'::character varying, 'DISPATCHING'::character varying, 'UNKNOWN'::character varying, 'ACKED'::character varying])::text[])))), ADD COLUMN "stop_intent_generation" bigint NOT NULL DEFAULT 0, ADD COLUMN "stop_requested_at" timestamptz NULL, ADD COLUMN "stop_requested_actor" character varying NULL, ADD COLUMN "close_dispatch_state" character varying NOT NULL DEFAULT 'IDLE', ADD COLUMN "close_attempt_count" bigint NOT NULL DEFAULT 0, ADD COLUMN "close_lease_generation" bigint NOT NULL DEFAULT 0, ADD COLUMN "close_lease_owner" character varying NULL, ADD COLUMN "close_lease_until" timestamptz NULL, ADD COLUMN "close_next_attempt_at" timestamptz NULL, ADD COLUMN "close_retry_blocked" boolean NOT NULL DEFAULT false, ADD COLUMN "close_last_error_code" character varying NULL, ADD COLUMN "close_receipt_canonical" bytea NULL;
